$ErrorActionPreference='Stop';$Root=Split-Path -Parent $MyInvocation.MyCommand.Path;$Dir=Join-Path $Root 'frontend\src\components\ContextMenu';if(-not(Test-Path (Join-Path $Root 'frontend\src\main.tsx'))){throw 'Execute na raiz do CloudOS-Unified.'};$Stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$Backup=Join-Path $Root "backup-contextmenu03-$Stamp";Copy-Item $Dir $Backup -Recurse -Force;Copy-Item (Join-Path $Root 'payload\frontend\src\components\ContextMenu\*') $Dir -Force;Push-Location $Root;try{& npm.cmd run lint;if($LASTEXITCODE){throw 'Lint falhou'};& npm.cmd run build;if($LASTEXITCODE){throw 'Build falhou'};& npm.cmd test;if($LASTEXITCODE){throw 'Testes falharam'};Write-Host "Menu 03 instalado. Backup: $Backup" -ForegroundColor Green}catch{Remove-Item $Dir -Recurse -Force;Copy-Item $Backup $Dir -Recurse -Force;throw}finally{Pop-Location}
